/// The `rustoverlay.v1` wire contract, generated by build.rs.
#[allow(clippy::all, missing_docs)]
pub mod proto {
    include!(concat!(env!("OUT_DIR"), "/rustoverlay.v1.rs"));
}

/// The agent version sent to the API and the relay, in .NET's four-part assembly form. Set at build
/// time from `RUSTOVERLAY_VERSION`; an unversioned build reports 1.0.0.0, as the C# agent did.
pub const AGENT_VERSION: &str = env!("RO_AGENT_VERSION");

pub(crate) fn unix_millis(at: std::time::SystemTime) -> i64 {
    // DateTimeOffset.ToUnixTimeMilliseconds floors, including before the epoch.
    match at.duration_since(std::time::UNIX_EPOCH) {
        Ok(after) => after.as_millis() as i64,
        Err(before) => {
            let d = before.duration();
            -((d.as_nanos().div_ceil(1_000_000)) as i64)
        }
    }
}
